    if (s.tradersLeft != 2 || std::strcmp(w.comment, "HERO_KILLED_TRADER") || w.commentKind || st.flag || w.setTimerId != 7) bad |= 2;
    w.killedByHero = false; s.tradersLeft = 3; w.comment = 0;
